public sealed class ProgressRing:FrameworkElement
{
    public double? Ratio{get;private set;}
    public void Observe(JobProgress? progress){Ratio=progress?.Completed is long done&&progress.Total is long total&&total>0&&done>=0&&done<=total?(double)done/total:null;InvalidateVisual();}
    protected override void OnRender(DrawingContext dc)
    {
        base.OnRender(dc);var center=new Point(ActualWidth/2,ActualHeight/2);double radius=Math.Max(0,Math.Min(ActualWidth,ActualHeight)/2-15);Brush accent=SystemParameters.HighContrast?SystemColors.HighlightBrush:(Brush)TryFindResource("AccentBrush");Brush line=SystemParameters.HighContrast?SystemColors.WindowTextBrush:(Brush)TryFindResource("LineBrush");dc.DrawEllipse(null,new Pen(line,12),center,radius,radius);if(Ratio is double value&&value>0){double angle=Math.Min(value,.9999)*Math.PI*2;var end=new Point(center.X+Math.Sin(angle)*radius,center.Y-Math.Cos(angle)*radius);var figure=new PathFigure{StartPoint=new Point(center.X,center.Y-radius)};figure.Segments.Add(new ArcSegment(end,new Size(radius,radius),0,angle>Math.PI,SweepDirection.Clockwise,true));var geometry=new PathGeometry([figure]);dc.DrawGeometry(null,new Pen(accent,12),geometry);}var text=new FormattedText(Ratio is double ratio?(ratio*100).ToString("0")+"%":"—",System.Globalization.CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),36,accent,VisualTreeHelper.GetDpi(this).PixelsPerDip);dc.DrawText(text,new Point(center.X-text.Width/2,center.Y-text.Height/2));
    }
}
